INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-ax44-bison', 1, 'Shoulder-Mounted Plasma Cannon', '6D6 M.D. per blast', 1, '1,500 ft (457 m)', 'Single shots only; each counts as one melee attack', 'Effectively unlimited; draws on the robot''s power supply', 'Laser targeting: +1 to strike on aimed shots', 'Anti-armor, secondarily assault. Flips back clear when idle, in the manner of a Glitter Boy''s Boom Gun.'),
  ('ng-ax44-bison', 2, 'Light Flamethrower (1)', '3D6 M.D. to the target and anyone within 5 ft (1.5 m); 1D6 M.D. on diesel or gasoline', 1, '150 ft (46 m)', 'Each burst counts as one melee action/attack', 'About 18 bursts from a 29 gallon (110 liter) reserve; refuel with military napalm, or diesel or gasoline at reduced damage', NULL, 'Anti-monster and anti-personnel, secondarily defense and assault. Right forearm. Waterproof and usable on the surface; valves seal it when submerged. Anyone caught in a bunker, cave or unsealed vehicle without environmental gear or air must save vs poison or fall unconscious for 1D4 melee rounds.'),
  ('ng-ax44-bison', 3, 'Ion Blaster (1)', '3D6 M.D. per single blast; 6D6 M.D. per simultaneous dual blast at one target', 1, '1,200 ft (366 m)', 'Each single or double blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel, secondarily defense. Double-barrel, short-range, on the left forearm.'),
  ('ng-ax44-bison', 4, 'Eye Lasers (2)', '2D6 M.D. per blast; 4D6 M.D. linked', 1, '1,200 ft (366 m)', 'Each single or dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel, secondarily defense. Backup guns for when the arms are busy, ammunition runs low or the cannon is unavailable.'),
  ('ng-v19-blocker', 1, 'Laser Turret', '6D6 M.D.', 1, '3,000 ft (914.4 m)', 'Each blast counts as one melee action/attack', 'Effectively unlimited', NULL, 'Anti-armor, secondarily anti-aircraft. A snub-nosed high-powered laser forming the head; 360 degree rotation and a 45 degree vertical arc.'),
  ('ng-v19-blocker', 2, 'Chest Mini-Missile Launchers (2)', 'By missile; plasma (1D6x10 M.D.) and armor piercing (1D4x10 M.D.) are standard', 1, 'About one mile (1.6 km)', 'One at a time or volleys of two or four', '36, 18 in each launcher', NULL, 'Anti-armor, secondarily anti-personnel. Concealed in the right and left chest; fired by the pilot.'),
  ('ng-v19-blocker', 3, 'Quad Ion Blasters (2, one each arm)', '3D6 M.D. single, 6D6 M.D. twin, 1D4x10+6 M.D. triple, 1D6x10+8 M.D. per simultaneous quadruple blast', 1, '1,200 ft (366 m)', 'Each single or multiple blast at one target counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily defense. Pop up from the forearms and retract after firing; the two arms cannot be linked at one target. Usually one hand holds the shield while the other wrist fires. Fired by the pilot.'),
  ('ng-v19-blocker', 4, 'Blocker Shield', 'None; halves missile, grenade and explosive damage and cancels blast radius', 0, NULL, NULL, NULL, NULL, 'Standard equipment, 24 ft (7.3 m) tall and 12 ft (3.6 m) wide, carried on the back. Loose armored slats let a blast''s shock wave pass through; rail gun rounds and energy blasts take full effect. Spent slats fall away to expose the next layer; at zero M.D.C. only the bare frame is left and it protects nothing. Its attacks are in the description.'),
  ('ng-v32-bruiser', 1, 'High-Impact Piston Arms & Super Punches', 'Jab 2D6 M.D.; elbow strike 3D6 M.D.; full strength punch 3D6+2 M.D.; piston power punch 1D6x10+2 M.D. (two attacks); one-two punch 2D6x10+3 M.D. (three attacks)', 1, 'Close combat, 15 ft (4.6 m) reach', 'As listed per attack', NULL, '+1 melee attack in a round spent attacking with the fists alone', 'Anti-armor, secondarily anti-fortification and defense. Damage is for P.S. 45 plus the hydraulics. A power punch or one-two punch gives a target under 13 ft (3.9 m) a 01-55% chance of being knocked down and thrown 1D4x10 ft (3 to 12.2 m), losing initiative and two attacks.'),
  ('ng-v32-bruiser', 2, 'Twin Ion Beam Turrets (2; light)', '5D6 M.D. single blast; 1D6x10 M.D. per simultaneous dual blast at one target', 1, '1,600 ft (488 m)', 'Each single or dual blast counts as one melee attack/action', 'Effectively unlimited; 50 dual blasts per charge on the electric battery model', 'Independent targeting: +1 to strike', 'Anti-armor and assault, secondarily anti-personnel and defense. Over the shoulders; each turns 360 degrees with a 90 degree vertical arc, separately or linked, both run by the one gunner. Their gun cameras back up the head''s sensors.'),
  ('ng-v32-bruiser', 3, 'Mini-Missile Launcher', 'By missile; plasma (1D6x10 M.D.) and armor piercing (1D4x10 M.D.) are standard', 1, 'About one mile (1.6 km)', 'One at a time or volleys of two or four', '16, 8 in each shoulder', NULL, 'Anti-armor and assault, secondarily anti-personnel and defense. Hatches in each upper shoulder; its only long-range weapon.'),
  ('ng-v32-bruiser', 4, 'Eye Lasers (2)', '2D6 M.D. per blast; 4D6 M.D. linked', 1, '1,200 ft (366 m)', 'Each single or dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel, secondarily defense. Backup guns in the recessed face.'),
  ('ng-v34-buffalo', 1, 'Twin Particle Beam Turrets (2; light)', '6D6+6 M.D. single blast; 2D4x10 M.D. per simultaneous dual blast at one target', 1, '1,600 ft (488 m)', 'Each single or linked dual blast counts as one melee attack/action', 'Effectively unlimited; 30 dual blasts per charge on the electric battery model', 'Laser targeting: +1 to strike on aimed shots', 'Anti-armor and assault, secondarily anti-fortification and defense. Above the shoulders; each turns 360 degrees with a 45 degree vertical arc, aimed separately by its own gunner or linked under one. Gun cameras back up the head''s sensors.'),
  ('ng-v34-buffalo', 2, 'Forearm Mounted Plasma Ejectors (2)', '5D6 M.D. per blast', 1, '1,600 ft (488 m)', 'Each single shot counts as one melee attack; the two arms cannot fire together at one target', 'Effectively unlimited; draws on the robot''s power supply', NULL, 'Anti-armor and assault, secondarily anti-personnel and defense. Fired by the pilot.'),
  ('ng-v34-buffalo', 3, 'Shoulder Mini-Missile Launchers (2)', 'By missile; plasma (1D6x10 M.D.) and armor piercing (1D4x10 M.D.) are standard', 1, 'About one mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6', '24, 12 in each launcher', NULL, 'Anti-armor and assault, secondarily anti-personnel and defense. In the particle beam cannons'' shoulder housings, under flip-up tops.'),
  ('ng-v34-buffalo', 4, 'Leg Mini-Missile Launchers (2)', 'By missile; armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.) standard, fragmentation (5D6 M.D.) against personnel', 1, 'About one mile (1.6 km)', 'One at a time or volleys of 2 or 4', '8, 4 in each upper leg', NULL, 'Anti-aircraft and anti-missile, secondarily anti-armor and anti-robot.'),
  ('ng-ex20-bulldog', 1, 'Main Gun Turret (1)', 'Laser 3D6 M.D. per blast; ion cannon 5D6 M.D. per blast; 1D4x10+4 M.D. per simultaneous dual blast at one target in range of both', 1, 'Laser 3,000 ft (914 m); ion cannon 1,200 ft (366 m); half underwater', 'Each single or dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Defense and anti-monster, secondarily anti-armor and anti-flyer. Open-air turret on top: a long-range laser over a shorter, harder-hitting ion cannon. Turns 360 degrees; 45 degree vertical arc to the sides or rear, 30 degrees aimed forward over the cockpit.'),
  ('ng-ex20-bulldog', 2, 'NG-501 Rail Gun', '1D4x10 M.D. per 40 round burst; the Gunwolf''s anti-supernatural rounds can be loaded', 1, '4,000 ft (1,219 m)', 'Each burst counts as one melee attack/action', '3,680 rounds (92 bursts) in two side-loaded detachable drums of 1,840 rounds (46 bursts)', NULL, 'Defense and anti-armor, secondarily anti-personnel. The nose gun, worked by a dedicated gunner; faces forward and moves 20 degrees in any direction.'),
  ('ng-ex20-bulldog', 3, 'Side-Mounted Mini-Missile Turret (1)', 'By missile; standard mix 60% high explosive (1D4x10 M.D.), 30% plasma (1D6x10 M.D.) and 10% smoke', 1, 'By missile type', 'One at a time or volleys of two, four or six; a single missile or a volley counts as one melee attack', '36 mini-missiles, or 12 short-range missiles', NULL, 'Defense and anti-monster, secondarily anti-armor and anti-missile. On a swivel arm on the left side, 180 degree rotation and 45 degree vertical arc. A short-range missile launcher can replace it for 500,000 credits more.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 machines are in' AS assertion, count(*) AS got, 5 AS want
  FROM vehicles WHERE slug IN ('ng-ax44-bison', 'ng-v19-blocker', 'ng-v32-bruiser', 'ng-v34-buffalo', 'ng-ex20-bulldog');
SELECT 'their 51 locations are in' AS assertion, count(*) AS got, 51 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-ax44-bison', 'ng-v19-blocker', 'ng-v32-bruiser', 'ng-v34-buffalo', 'ng-ex20-bulldog');
SELECT 'their 19 weapon entries are in' AS assertion, count(*) AS got, 19 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-ax44-bison', 'ng-v19-blocker', 'ng-v32-bruiser', 'ng-v34-buffalo', 'ng-ex20-bulldog');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-ax44-bison', 'ng-v19-blocker', 'ng-v32-bruiser', 'ng-v34-buffalo', 'ng-ex20-bulldog') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

